args.command:
$dosyalar = Get-ChildItem -Path "loglar" -Recurse -Include "*.log" | Where-Object { $_.Extension -eq ".log" }
$result = @()

foreach ($dosya in $dosyalar) {
    $errorCount = 0
    $warnCount = 0
    $infoCount = 0

    # Dosyanın içeriğini satır satır okuyoruz
    $lines = Get-Content $dosya.FullName
    foreach ($line in $lines) {
        if ($line -match "^\d{4}-\d{2}-\d{2} \d{2}:\d{2}:\d{2} ERROR ") {
            $errorCount++
        } elseif ($line -match "^\d{4}-\d{2}-\d{2} \d{2}:\d{2}:\d{2} WARN ") {
            $warnCount++
        } elseif ($line -match "^\d{4}-\d{2}-\d{2} \d{2}:\d{2}:\d{2} INFO ") {
            $infoCount++
        }
    }

    # Dosya yolu (relative path) alıyoruz
    $relativePath = $dosya.FullName.Replace("loglar", "").TrimStart("\")

    # Sonuçları listeye ekliyoruz
    $result += [PSCustomObject]@{
        dosya = $relativePath
        error = $errorCount
        warn = $warnCount
        info = $infoCount
    }
}

# Sıralama: ERROR sayısına göre azalan, eşitlik durumunda dosya adına göre artan
$siraliSonuc = $result | Sort-Object -Property @{e={$_.error}; desc=$true}, @{e={$_.dosya}; desc=$false}

# CSV'ye yazıyoruz
$siraliSonuc | Export-Csv -Path "rapor.csv" -NoTypeInformation

Write-Host "CSV dosyası oluşturuldu."

